import{_ as o,o as t,c as i,ag as d}from"./chunks/framework.B45avKwg.js";const h=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),r={name:"changelog.md"};function n(a,e,c,s,l,g){return t(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to this project will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h3 id="unreleased-—-v0-4-0-planned" tabindex="-1">[Unreleased] — v0.4.0 (planned) <a class="header-anchor" href="#unreleased-—-v0-4-0-planned" aria-label="Permalink to &quot;[Unreleased] — v0.4.0 (planned)&quot;">​</a></h3><h3 id="_0-3-1-2026-05-26" tabindex="-1">[0.3.1] - 2026-05-26 <a class="header-anchor" href="#_0-3-1-2026-05-26" aria-label="Permalink to &quot;[0.3.1] - 2026-05-26&quot;">​</a></h3><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>SPG Phase 6a — Semantic Program Graph exposed in context</strong>: <code>&amp;SemanticGraph</code> available to all rule types via <code>AuditOptions.graph</code> / <code>GenSenseContext.graph</code>. Enables cross-cutting queries that span file boundaries.</li><li><strong>SPG Phase 6b — Taint edges materialized in graph</strong>: After each file audit, taint-related advisories are recorded as <code>TaintFlow</code> edges in the <code>SemanticGraph</code>. Accessible via <code>graph.taint_flows</code> and <code>graph.name_index</code>.</li><li><strong>SPG Phase 6c — Algebraic flow combinators</strong>: 6 new <code>FlowConstraint</code> variants (<code>AllOf</code>, <code>AnyOf</code>, <code>Not</code>, <code>Across</code>, <code>Without</code>, <code>Chain</code>) with <code>FlowEvaluator</code> recursive tree-walk evaluator. Compound rule queries from YAML DSL fields (<code>across_boundary</code>, <code>all_of</code>, <code>any_of</code>, <code>not</code>, <code>without_constraint</code>, <code>without_exclusion</code>).</li><li><strong>6 tuning parameters exposed</strong>: <code>--max-source-lines</code>, <code>--ngram-window</code>, <code>--min-ngram-count</code>, <code>--taint-conf-inter</code>, <code>--taint-conf-intra</code>, <code>--taint-max-depth</code> CLI flags with setters and default values on <code>Engine</code>.</li><li><strong><code>LongFile</code> configurable threshold</strong>: <code>LongFile::new(max_lines)</code> replaces unit struct; <code>remove_rule</code>/<code>add_rule</code> plumbing for dynamic rule replacement.</li><li><strong>N-gram fingerprint window configurable</strong>: <code>extract_fingerprints(window_size)</code> via <code>AuditOptions</code>.</li><li><strong>Taint confidence configurable</strong>: Reads from <code>self.context</code> instead of hardcoded <code>0.80</code> / <code>0.90</code>.</li><li><strong>Default taint max depth configurable</strong>: Reads from <code>self.context</code> instead of hardcoded <code>5</code>.</li><li><strong>CSA delegation suppression test</strong>: <code>body_may_delegate_via</code> now tested — functions delegating to <code>safeParse</code>/<code>validate</code>/<code>verify</code>/<code>check</code>/<code>assert</code> are correctly excluded from findings.</li><li><strong>Rule quality pipeline</strong>: Every rule now carries a <code>precision</code> tier (<code>very-high | high | medium | low</code>), letting users choose a rule suite via <code>--suite {default|extended|all}</code>.</li><li><strong><code>--suite</code> CLI flag</strong>: <code>gensense --suite default path/</code> filters to high-confidence findings only.</li><li><strong>Native TypeScript rule <code>TS_TAUTOLOGICAL_ASSERT</code></strong>: Detects <code>expect(x).toBe(x)</code>, <code>expect(true).toBeTruthy()</code>, <code>expect(null).toBeNull()</code>.</li><li><strong><code>temporal</code> feature flag</strong>: Gates <code>TemporalAnalyzer</code>, <code>TemporalConfig</code>, and all temporal compilation/execution paths.</li><li><strong>RUST_LOCK_SLEEP temporal rule</strong>: Detects <code>lock()</code> followed by <code>sleep()</code> in the same scope.</li><li><strong>CSA test coverage</strong>: All 5 CSA rules (RUST + 4 TS) now have positive/negative corpus fixtures and <code>run_test()</code> functions. <code>SOL_*</code> rules removed.</li><li><strong>CLI defaults to <code>.</code></strong>: <code>gensense</code> with no path argument now scans the current directory.</li><li><strong>Full <code>--help</code> rewrite</strong>: All 19 CLI flags documented in categorized sections (Analysis, Confidence &amp; Tuning, Output, Development) with 8 examples.</li><li><strong>README rewritten</strong>: Simplified from 357→250 lines, v0.3.1 features, deduplicated suppression section.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong><code>perform_parallel_audit</code> signature</strong>: <code>&amp;SymbolRegistry</code> → <code>&amp;mut SymbolRegistry</code> to support graph mutation during audit.</li><li><strong>Precision assigned to all 75 rules</strong>: 6 Rust hand-written rules set to <code>very-high</code>, 2 AI-pattern rules set to <code>high</code>, 65 YAML rules tiered by confidence score.</li><li><strong>Consolidated single-binaries into unified crate</strong>: <code>cargo install gensense</code> now produces both <code>gensense</code> and <code>gensense-mcp</code> binaries.</li><li><strong>MCP filter params</strong>: Added <code>language</code> (file extension) and <code>rules</code> (rule_id set) filters to <code>gensense_audit</code> tool.</li><li><strong>Clippy pedantic compliance</strong>: All ~35 <code>clippy::pedantic</code> violations fixed.</li><li><strong>Temporal analyzer moved to dedicated folder</strong>: <code>src/temporal/</code> consolidates temporal code.</li><li><strong>License headers</strong>: MIT license on all 13 previously unattributed files. Solidity rules changed to MIT.</li><li><strong>GAP_ANALYSIS.md</strong>: Phase 2a/2c marked complete. Updated Summary table.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>MCP tests</strong>: 36/36 pass including <code>test_mcp_language_filter</code>, <code>test_mcp_rules_filter</code>.</li><li><strong>Binary file crash</strong>: <code>collect_files</code> filters to supported extensions, preventing UTF-8 panic.</li><li><strong>Package.json</strong>: Removed non-existent <code>index.js</code> from <code>files</code> array.</li></ul><h3 id="removed" tabindex="-1">Removed <a class="header-anchor" href="#removed" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li><strong>14 style/noise YAML rules</strong>: Self-audit findings dropped from 186 to 69.</li><li><strong>10 Solidity rules and feature</strong>: Dead code — <code>solidity</code> feature removed, no tree-sitter support.</li><li><strong>Old bug tracking docs</strong>: <code>V0_3_1_ISSUES.md</code>, <code>V0_3_1_REPORT.md</code>, <code>AUDIT_V0.3.0_REPORT.md</code> superseded by <code>GAP_ANALYSIS.md</code>.</li></ul><h3 id="_0-3-0-2026-05-21" tabindex="-1">[0.3.0] - 2026-05-21 <a class="header-anchor" href="#_0-3-0-2026-05-21" aria-label="Permalink to &quot;[0.3.0] - 2026-05-21&quot;">​</a></h3><h3 id="changed-breaking" tabindex="-1">Changed (Breaking) <a class="header-anchor" href="#changed-breaking" aria-label="Permalink to &quot;Changed (Breaking)&quot;">​</a></h3><ul><li><strong>Rust API: <code>GenSenseAuditor::audit</code></strong>: Consolidated 10+ arguments into a single, extensible <code>AuditOptions</code> struct. This simplifies the call site and future-proofs the audit pipeline.</li><li><strong>Rust API: <code>GenSenseRule::new_remediation</code></strong>: Added a mandatory <code>import: Option&lt;String&gt;</code> parameter to support auto-injection of missing imports during patching.</li><li><strong>Rust API: <code>CoreRuleIr::query</code></strong>: Always returns the compiled query string; removed <code>use_query</code> guard. All YAML node-kind rules now participate in the combined query.</li><li><strong>Data Model: <code>Advisory</code></strong>: Added mandatory fields <code>proposed_import</code>, <code>enclosing_symbol</code>, <code>confidence</code>, and <code>fingerprint</code> for higher fidelity result tracking.</li><li><strong>Edition Upgrade</strong>: The project now requires <strong>Rust 2024 Edition</strong>.</li><li><strong>Parallelism removed</strong>: Rayon <code>into_par_iter()</code> replaced with <code>into_iter()</code> in snapshot collection and audit phases — eliminates futex deadlock class while maintaining adequate performance (~4.5s for 68 files).</li></ul><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Schema Contract Validation</strong>: New <code>ProjectFlowConstraint::SchemaContract</code> variant with <code>SchemaType</code>/<code>SchemaExtract</code> enums. Flattened DSL fields (<code>source_ext</code>, <code>source_pattern</code>, <code>source_file_glob</code>, <code>schema_type</code>, <code>schema_glob</code>, <code>schema_extract</code>) on <code>ProjectCoreRule</code>. Block-aware Prisma extractor replaces fragile line-based parser. Standard DB rules in <code>cross-layer-contracts.yml</code>.</li><li><strong>MCP Server Binary</strong>: <code>gensense-mcp</code> — full JSON-RPC 2.0 over stdin/stdout. Tool <code>gensense_audit</code> returns <code>{clean, advisories, auto_fixed, requires_human}</code> with <code>severity_threshold</code> filtering and optional <code>fix_auto</code>. 35 integration tests (34 pass, 1 ignored in debug mode).</li><li><strong>Field-Path Taint Propagation</strong>: <code>TaintRegistry::get_any_field_origin</code> detects whole-object leaks when only specific fields are tainted. <code>resolve_taint</code> now falls back to field-taint check for identifiers.</li><li><strong>Combined Tree-Sitter Query</strong>: Single AST traversal per language merges all rule queries into one multi-pattern query. Capture names encode rule IDs (<code>@{rule_id}.node</code>). <code>HashSet&lt;(rule_idx, node_id)&gt;</code> dedup prevents redundant <code>check()</code> calls. Eliminates O(F × R × T) scaling.</li><li><strong>Cached <code>run_content</code> Init</strong>: Only calls <code>initialize_auditor_and_config</code> on first invocation (~243ms saved per subsequent call).</li><li><strong>Schema Documentation</strong>: <code>BENCHMARK.md</code> with criterion benchmark results.</li><li><strong>CI: Benchmark Dashboard</strong>: <code>pages</code> job publishes criterion report via GitHub Pages.</li><li><strong>CI: <code>--force</code> install</strong>: <code>cargo install cargo-hack --locked</code> and <code>cargo install cargo-machete --locked</code> use <code>--force</code> to handle cached binaries.</li><li><strong>Missing Tests</strong>: <code>test_non_remediated_advisory_is_not_auto_fixable</code>, <code>test_requires_human_is_true_for_project_rule_advisories</code>, <code>test_prisma_extractor_handles_model_with_block_on_same_line</code>, <code>test_prisma_extractor_handles_multiple_schema_files</code>, <code>test_mcp_audit_response_contains_requires_human_field</code>, <code>test_mcp_audit_auto_fixed_is_zero_when_no_fixable_advisories</code>.</li></ul><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>MCP Null-ID Hang</strong>: JSON-RPC <code>&quot;id&quot;: null</code> no longer hangs — <code>RequestId</code> enum (<code>Absent | Null | Value</code>) with custom deserializer replaces <code>Option&lt;Value&gt;</code>.</li><li><strong>Sink/Source Matching</strong>: <code>analyze_call</code> checks both short <code>fn_name</code> and full call expression text against sink/source regex — fixes <code>console.log(payload)</code> matching when semantic op extracts only <code>&quot;log&quot;</code>.</li><li><strong>Cross-Layer Contracts Regex</strong>: Table pattern requires PascalCase (<code>&#39;&quot;?([A-Z][a-zA-Z0-9]+)&quot;?&#39;</code>), column pattern requires double-quoted camelCase — drastically reduces false positives.</li><li><strong>Prisma Extractor</strong>: Block-aware state machine replaces line-based parser — correctly handles model/enum boundaries and same-line braces.</li><li><strong><code>find_project_root</code></strong>: Prefers <code>std::env::current_dir()</code> unconditionally over fragile source-path marker-file heuristics.</li><li><strong>Governance Check</strong>: <code>MISSING_SBOM</code> removed from automatic <code>run_detailed</code> — kept as <code>Engine::run_governance_checks()</code> opt-in helper.</li><li><strong>Build Artifacts in Git</strong>: Purged 53 build artifact files from git history via <code>git filter-repo</code>.</li><li><strong>Benchmark Raw String</strong>: Fixed <code>r#&quot;...&quot;#</code> delimiter clash in <code>engine_perf.rs</code>.</li><li><strong><code>SymbolKind::Method</code> → <code>Struct</code></strong>: Updated deprecated <code>SymbolKind</code> variant in benchmarks.</li><li><strong>Baseline Resilience</strong>: Resolved &quot;Line-Drift&quot; fragility where vertical code shifts would cause false positive regression failures.</li><li><strong>Engine: Extension Matching</strong>: Fixed <code>applies_to</code> to correctly handle multi-extension strings (e.g., <code>ts|js|tsx|jsx</code>).</li><li><strong>Engine: Query Safety</strong>: Implemented graceful skipping of language-incompatible Tree-sitter queries during cross-language scans.</li><li><strong>CLI: Descriptive Reporting</strong>: Updated reporting to include regression/resolved summaries and net change metrics.</li><li><strong>JS/NAPI SRI Bridge</strong>: Exposed semantic anchoring metadata to the Node.js API for consistent identity tracking.</li></ul><h2 id="_0-2-2-2026-05-14" tabindex="-1">[0.2.2] - 2026-05-14 <a class="header-anchor" href="#_0-2-2-2026-05-14" aria-label="Permalink to &quot;[0.2.2] - 2026-05-14&quot;">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Solidity Beta Support</strong>: Integrated tree-sitter-solidity. Enable with <code>--features solidity</code>.</li><li><strong>Enhanced Temporal Rules</strong>: Added <code>forbidden_between</code> behavior to allow detecting prohibited calls between specific state boundaries.</li><li><strong>Architectural Guardrails</strong>: Added comprehensive documentation and project-level rules for enforcing system architecture (e.g., service/handler separation).</li></ul><h2 id="_0-2-1-2026-05-13" tabindex="-1">[0.2.1] - 2026-05-13 <a class="header-anchor" href="#_0-2-1-2026-05-13" aria-label="Permalink to &quot;[0.2.1] - 2026-05-13&quot;">​</a></h2><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>CI: Missing Rust toolchain in <code>publish-npm</code> job</strong>: <code>cargo run</code> was called before Rust was installed, causing NPM to never publish past v0.1.4.</li><li><strong>CI: NAPI features included in <code>cargo publish</code></strong>: Default features pulled in <code>napi-build</code> unconditionally, causing <code>cargo package</code> to fail in environments without NAPI headers. Scoped to <code>--no-default-features --features rust,typescript,fingerprinting,remediation</code>.</li><li><strong>CI: <code>aarch64-apple-darwin</code> cross-compiled on wrong host</strong>: Changed <code>macos-latest</code> (x86) to <code>macos-14</code> (Apple Silicon) for native arm64 builds.</li><li><strong>CI: Mutable action tags</strong>: All GitHub Action references pinned to immutable SHA digests.</li><li><strong>CI: Broad branch trigger</strong>: <code>ci.yml</code> narrowed from <code>[&quot;**&quot;]</code> to <code>main</code>, <code>feature/**</code>, and <code>fix/**</code>.</li><li><strong>CI: <code>npm install</code> fallback</strong>: Replaced <code>npm ci || npm install</code> with strict <code>npm ci</code>.</li><li><strong>CI: Sync loop guard</strong>: <code>sync.yml</code> now also skips its own &quot;sync version&quot; commits to prevent re-trigger loops.</li><li><strong>CI: Concurrency controls</strong>: Added <code>concurrency</code> groups to all three workflows to prevent duplicate runs.</li></ul><h2 id="_0-2-0-2026-05-13" tabindex="-1">[0.2.0] - 2026-05-13 <a class="header-anchor" href="#_0-2-0-2026-05-13" aria-label="Permalink to &quot;[0.2.0] - 2026-05-13&quot;">​</a></h2><h3 id="added-3" tabindex="-1">Added <a class="header-anchor" href="#added-3" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Multi-File Scanning (GenSense 2.0)</strong>: Stabilized the core semantic architecture to support project-wide auditing.</li><li><strong>Graph-First Semantic Engine</strong>: Migrated to a global symbol graph for high-precision inter-procedural taint analysis across files.</li><li><strong>Multi-Pass Audit Loop</strong>: Implemented a sophisticated audit pipeline that performs local AST checks followed by cross-file project-level enforcement.</li><li><strong>Cross-File Project Rules</strong>: Full support for <code>MustHaveGuard</code>, <code>MustBeInternal</code>, and <code>CrossFileTaintFree</code> rules.</li><li><strong>Node.js API Extensions</strong>: Exposed <code>auditProject</code> and <code>auditPath</code> for full project-wide scanning from JavaScript.</li><li><strong>Supply Chain Security</strong>: Integrated <code>cargo deny</code>, <code>npm audit</code>, and SLSA Level 3 provenance for production-grade security.</li><li><strong>Egress Auditing</strong>: Integrated StepSecurity Harden Runner for CI network protection.</li></ul><h3 id="fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-3" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>BFS Deduplication</strong>: Fixed a critical bug where BFS traversal incorrectly deduplicated symbols with the same name across different files.</li><li><strong>Project Advisory Metadata</strong>: Resolved an issue where <code>original_content</code> was empty for project-level findings, unblocking <code>--fix</code> mode.</li><li><strong>JS API Gaps</strong>: Fixed <code>audit_content</code> incorrectly being used for project-wide rules; redirected users to the new <code>audit_project</code> method.</li><li><strong>Clippy Violations</strong>: Fixed several redundant cast warnings and unnecessary cloning identified by static analysis.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li><strong>MSRV Bump</strong>: Increased Minimum Supported Rust Version (MSRV) to <strong>1.77</strong> to support modern build script features.</li><li><strong>CI Hardening</strong>: Pinned all GitHub Action references to full immutable SHAs to prevent supply chain attacks.</li><li><strong>DSL Cleanup</strong>: Removed the redundant and unused <code>domain</code> field from rule definitions to simplify the DSL.</li></ul><h3 id="removed-1" tabindex="-1">Removed <a class="header-anchor" href="#removed-1" aria-label="Permalink to &quot;Removed&quot;">​</a></h3><ul><li>Unused <code>domain</code> metadata from all core and embedded rule definitions.</li></ul>',35)])])}const p=o(r,[["render",n]]);export{h as __pageData,p as default};
